#!/usr/bin/env node
// Local UI performance guard for the dmslog viewer (issue #144, UI-04).
//
// Node >= 22, no dependencies: native WebSocket, the system Chrome or Edge driven through the DevTools
// protocol, and `dmslog serve` over a synthetic case generated by tools/bench.py (never local-samples/).
//
// Measures: first grid row, request count and bytes on open and on reload, CLS of the opening, forced
// layouts and main-thread work per frame over 120 wheel events, INP of click, arrow keys, filter and
// search. Prints a table and JSON, compares with tools/ui_perf_budgets.json and exits 1 on a budget miss.
//
//   node tools/ui_perf.mjs                      # bench --quick case, CPU 1x
//   node tools/ui_perf.mjs --cpu 4              # CPU throttled 4x (budget reference)
//   node tools/ui_perf.mjs --large --cpu 4      # 500 MB case (about 3.5 million records, needs ~1.5 GB)
//   node tools/ui_perf.mjs --json out.json --report-only
//
// Everything created (case, data dir, browser profile, server, browser) is removed or stopped at the end,
// also on errors and on SIGINT/SIGTERM.

import { spawn, spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, "..");
const DEFAULT_BUDGETS = path.join(HERE, "ui_perf_budgets.json");
const WHEEL_EVENTS = 120;
const SETTLE_MS = 1500;
const MAIN_THREAD = "CrRendererMain";

// ---------------------------------------------------------------------------------------------------
// Pure functions (exported and unit-tested without a browser)
// ---------------------------------------------------------------------------------------------------

export function parseArgs(argv) {
  const opts = {
    large: false, sizeMb: null, adapters: null, profile: null, cpu: 1, json: null, budgets: DEFAULT_BUDGETS,
    browser: null, python: process.env.DMSLOG_PYTHON || (process.platform === "win32" ? "python" : "python3"),
    reportOnly: false, headed: false, searchTerm: "timeout", help: false,
  };
  const need = (i, name) => {
    if (i + 1 >= argv.length) throw new Error(`${name} needs a value`);
    return argv[i + 1];
  };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--quick") { opts.large = false; opts.sizeMb = null; }
    else if (a === "--large") opts.large = true;
    else if (a === "--size-mb") { opts.sizeMb = Number(need(i, a)); i++; }
    else if (a === "--adapters") { opts.adapters = Number(need(i, a)); i++; }
    else if (a === "--profile") { opts.profile = need(i, a); i++; }
    else if (a === "--cpu") { opts.cpu = Number(need(i, a)); i++; }
    else if (a === "--json") { opts.json = need(i, a); i++; }
    else if (a === "--budgets") { opts.budgets = need(i, a); i++; }
    else if (a === "--browser") { opts.browser = need(i, a); i++; }
    else if (a === "--python") { opts.python = need(i, a); i++; }
    else if (a === "--search") { opts.searchTerm = need(i, a); i++; }
    else if (a === "--report-only") opts.reportOnly = true;
    else if (a === "--headed") opts.headed = true;
    else if (a === "--help" || a === "-h") opts.help = true;
    else throw new Error(`unknown argument: ${a}`);
  }
  if (!Number.isFinite(opts.cpu) || opts.cpu < 1) throw new Error("--cpu must be a number >= 1");
  for (const key of ["sizeMb", "adapters"]) {
    if (opts[key] !== null && (!Number.isFinite(opts[key]) || opts[key] <= 0)) {
      throw new Error(`--${key === "sizeMb" ? "size-mb" : key} must be a positive number`);
    }
  }
  return opts;
}

export const USAGE = `Usage: node tools/ui_perf.mjs [options]

  --quick            Small synthetic case (bench.py --quick). Default.
  --large            500 MB synthetic case, 8 adapters, info profile (about 3.5 million records).
  --size-mb N        Custom synthetic case size (with --adapters, --profile).
  --cpu N            Emulate a CPU N times slower (budget reference is 4).
  --json PATH        Also write the result as JSON.
  --budgets PATH     Budget file (default: tools/ui_perf_budgets.json).
  --report-only      Print the comparison but always exit 0.
  --browser PATH     Chrome or Edge executable (default: auto-detect).
  --python PATH      Python for bench.py and dmslog (default: $DMSLOG_PYTHON, python3, python on Windows).
  --search TERM      Search term for the INP of search (default: timeout).
  --headed           Show the browser window.
`;

/** Validates the budget file shape. Returns a list of problems (empty when valid). */
export function validateBudgets(doc) {
  const problems = [];
  if (!doc || typeof doc !== "object" || Array.isArray(doc)) return ["root must be an object"];
  if (doc.schema !== 1) problems.push("schema must be 1");
  if (!doc.reference || typeof doc.reference !== "object") problems.push("reference must be an object");
  if (!doc.budgets || typeof doc.budgets !== "object" || Array.isArray(doc.budgets)) {
    problems.push("budgets must be an object");
    return problems;
  }
  for (const [key, b] of Object.entries(doc.budgets)) {
    if (!b || typeof b !== "object") { problems.push(`${key}: must be an object`); continue; }
    if (typeof b.max !== "number" || !Number.isFinite(b.max)) problems.push(`${key}: max must be a number`);
    if (typeof b.unit !== "string" || !b.unit) problems.push(`${key}: unit must be a non-empty string`);
    if (typeof b.label !== "string" || !b.label) problems.push(`${key}: label must be a non-empty string`);
    if (b.warn !== undefined && (typeof b.warn !== "number" || b.warn > b.max)) {
      problems.push(`${key}: warn must be a number <= max`);
    }
    if (b.baseline !== undefined && typeof b.baseline !== "number") problems.push(`${key}: baseline must be a number`);
  }
  return problems;
}

/** Compares measurements with budgets. status: pass | warn | fail | n/a (no measurement). */
export function compareBudgets(measures, budgets) {
  const rows = [];
  for (const [key, b] of Object.entries(budgets.budgets)) {
    const value = measures[key];
    let status = "n/a";
    if (typeof value === "number" && Number.isFinite(value)) {
      if (value > b.max) status = "fail";
      else if (b.warn !== undefined && value > b.warn) status = "warn";
      else status = "pass";
    }
    rows.push({
      key, label: b.label, unit: b.unit, value: value ?? null, max: b.max, warn: b.warn ?? null,
      baseline: b.baseline ?? null, status,
    });
  }
  return rows;
}

export function deltaPercent(value, baseline) {
  if (typeof value !== "number" || typeof baseline !== "number" || baseline === 0) return null;
  return ((value - baseline) / baseline) * 100;
}

export function hasFailures(rows) {
  return rows.some((r) => r.status === "fail");
}

export function formatTable(rows) {
  const fmt = (v) => (v === null || v === undefined ? "-" : Number.isInteger(v) ? String(v) : v.toFixed(2));
  const header = ["Measure", "Value", "Budget", "Baseline", "Delta", "Status"];
  const body = rows.map((r) => {
    const d = deltaPercent(r.value, r.baseline);
    return [
      `${r.label} (${r.unit})`, fmt(r.value), `<= ${fmt(r.max)}`, fmt(r.baseline),
      d === null ? "-" : `${d >= 0 ? "+" : ""}${d.toFixed(0)}%`, r.status.toUpperCase(),
    ];
  });
  const widths = header.map((h, i) => Math.max(h.length, ...body.map((row) => row[i].length)));
  const line = (cells) => cells.map((c, i) => (i === 0 ? c.padEnd(widths[i]) : c.padStart(widths[i]))).join("  ");
  return [line(header), widths.map((w) => "-".repeat(w)).join("  "), ...body.map(line)].join("\n");
}

/**
 * Reduces DevTools trace events of one scroll window to per-frame numbers.
 * A layout is "forced" when it runs inside a script (FunctionCall/EventDispatch/...) on the renderer
 * main thread; layouts of the normal frame lifecycle are not. `frames` is the number of frames the
 * window produced (one wheel event per frame in this tool); work per frame divides by it.
 */
export function analyzeTrace(events, frames) {
  const mainThreads = new Set();
  for (const e of events) {
    if (e.ph === "M" && e.name === "thread_name" && e.args && e.args.name === MAIN_THREAD) {
      mainThreads.add(`${e.pid}:${e.tid}`);
    }
  }
  const onMain = events.filter((e) => mainThreads.has(`${e.pid}:${e.tid}`) && e.ph === "X" && typeof e.dur === "number");
  const SCRIPT = new Set(["FunctionCall", "EventDispatch", "RunMicrotasks", "TimerFire", "FireAnimationFrame", "V8.Execute"]);
  const scripts = onMain.filter((e) => SCRIPT.has(e.name));
  const layouts = onMain.filter((e) => e.name === "Layout");
  const styles = onMain.filter((e) => e.name === "UpdateLayoutTree" || e.name === "RecalculateStyles");
  const tasks = onMain.filter((e) => e.name === "RunTask");
  const inside = (outer, inner) => inner.ts >= outer.ts && inner.ts + inner.dur <= outer.ts + outer.dur;
  const forced = layouts.filter((l) => scripts.some((s) => inside(s, l)));
  // Script time without double counting nested script events: keep only outermost intervals.
  const sorted = [...scripts].sort((a, b) => a.ts - b.ts || b.dur - a.dur);
  let scriptUs = 0;
  let end = -Infinity;
  for (const s of sorted) {
    const sEnd = s.ts + s.dur;
    if (sEnd <= end) continue;
    scriptUs += sEnd - Math.max(s.ts, end);
    end = sEnd;
  }
  const sum = (list) => list.reduce((acc, e) => acc + e.dur, 0);
  const layoutUs = sum(layouts);
  const styleUs = sum(styles);
  const workUs = scriptUs + layoutUs + styleUs;
  return {
    forced_layouts: forced.length,
    layouts: layouts.length,
    frames,
    script_ms: scriptUs / 1000,
    style_ms: styleUs / 1000,
    layout_ms: layoutUs / 1000,
    max_layout_ms: layouts.reduce((m, e) => Math.max(m, e.dur), 0) / 1000,
    work_per_frame_ms: workUs / 1000 / Math.max(1, frames),
    long_tasks: tasks.filter((t) => t.dur > 50_000).length,
  };
}

/** Largest duration of the interaction events (Event Timing entries with an interactionId). */
export function interactionDuration(entries) {
  return entries.filter((e) => e.interactionId > 0).reduce((m, e) => Math.max(m, e.duration), 0);
}

/** Flat measure map (the keys used by the budget file) from the raw runs. */
export function buildMeasures(raw) {
  const m = {};
  const open = raw.open;
  const reload = raw.reload;
  m.first_row_cold_ms = open.firstRowMs;
  m.first_row_reload_ms = reload.firstRowMs;
  m.requests_open = open.staticRequests + 1; // static files plus the document, as in analysis 3
  m.requests_reload_non_304 = reload.staticRequests + 1 - reload.notModified;
  m.js_kb_open = open.jsBytes / 1024;
  m.js_modules_open = open.jsFiles;
  m.css_files_open = open.cssFiles;
  m.css_late_injections = open.cssLateInjections;
  m.api_call_max_ms = open.apiMaxMs;
  m.cls_open = open.cls;
  m.inp_click_ms = raw.inp.click;
  m.inp_keys_ms = raw.inp.keys;
  m.inp_filter_ms = raw.inp.filter;
  m.inp_search_ms = raw.inp.search;
  m.filter_to_rows_ms = raw.toRows.filter;
  m.search_to_rows_ms = raw.toRows.search;
  m.scroll_forced_layouts = raw.scroll.forced_layouts;
  m.scroll_work_per_frame_ms = raw.scroll.work_per_frame_ms;
  m.scroll_long_tasks = raw.scroll.long_tasks;
  return m;
}

// ---------------------------------------------------------------------------------------------------
// Process, temp and browser plumbing
// ---------------------------------------------------------------------------------------------------

const children = new Set();
const tempDirs = new Set();
let cleaned = false;

function killTree(child) {
  if (!child || child.exitCode !== null || child.signalCode !== null || !child.pid) return;
  try {
    if (process.platform === "win32") {
      spawnSync("taskkill", ["/pid", String(child.pid), "/T", "/F"], { stdio: "ignore" });
    } else {
      process.kill(-child.pid, "SIGKILL"); // own process group (detached), takes the browser helpers too
    }
  } catch {
    try { child.kill("SIGKILL"); } catch { /* already gone */ }
  }
}

function removeDir(dir) {
  for (let attempt = 0; attempt < 5; attempt++) {
    try {
      fs.rmSync(dir, { recursive: true, force: true });
      return;
    } catch {
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 200); // Windows may hold handles briefly
    }
  }
  console.error(`ui_perf: could not remove ${dir}`);
}

function cleanup() {
  if (cleaned) return;
  cleaned = true;
  for (const child of children) killTree(child);
  for (const dir of tempDirs) removeDir(dir);
}

function spawnTracked(command, args, options = {}) {
  const child = spawn(command, args, { detached: process.platform !== "win32", windowsHide: true, ...options });
  children.add(child);
  child.once("exit", () => children.delete(child));
  return child;
}

function runToCompletion(command, args, options = {}) {
  return new Promise((resolve, reject) => {
    const child = spawnTracked(command, args, { stdio: ["ignore", "pipe", "pipe"], ...options });
    let out = "";
    child.stdout.on("data", (d) => { out += d; });
    child.stderr.on("data", (d) => { out += d; });
    child.once("error", reject);
    child.once("exit", (code) => (code === 0 ? resolve(out) : reject(new Error(`${command} exited ${code}\n${out.slice(-2000)}`))));
  });
}

function waitForLine(child, stream, regex, timeoutMs, what) {
  return new Promise((resolve, reject) => {
    let buffer = "";
    const timer = setTimeout(() => reject(new Error(`timeout waiting for ${what}`)), timeoutMs);
    const onData = (d) => {
      buffer += d;
      const match = regex.exec(buffer);
      if (match) { clearTimeout(timer); resolve(match); }
    };
    stream.on("data", onData);
    child.once("exit", (code) => { clearTimeout(timer); reject(new Error(`${what}: process exited ${code}\n${buffer.slice(-1500)}`)); });
  });
}

export function browserCandidates(platform = process.platform, env = process.env) {
  if (platform === "win32") {
    const roots = [env["PROGRAMFILES(X86)"], env.PROGRAMFILES, env.LOCALAPPDATA].filter(Boolean);
    const rel = [["Microsoft", "Edge", "Application", "msedge.exe"], ["Google", "Chrome", "Application", "chrome.exe"]];
    return rel.flatMap((r) => roots.map((root) => path.join(root, ...r)));
  }
  if (platform === "darwin") {
    return [
      "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
      "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge",
    ];
  }
  const names = ["google-chrome-stable", "google-chrome", "chromium", "chromium-browser", "microsoft-edge-stable", "microsoft-edge"];
  const dirs = (env.PATH || "").split(path.delimiter).filter(Boolean);
  return dirs.flatMap((d) => names.map((n) => path.join(d, n)));
}

function findBrowser(explicit) {
  if (explicit) {
    if (!fs.existsSync(explicit)) throw new Error(`browser not found: ${explicit}`);
    return explicit;
  }
  const found = browserCandidates().find((p) => fs.existsSync(p));
  if (!found) throw new Error("no Chrome or Edge found; pass --browser PATH");
  return found;
}

/** Minimal DevTools protocol client over the native WebSocket. */
class Cdp {
  constructor(url) {
    this.ws = new WebSocket(url);
    this.nextId = 1;
    this.pending = new Map();
    this.listeners = [];
    this.ws.addEventListener("message", (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id !== undefined) {
        const p = this.pending.get(msg.id);
        if (!p) return;
        this.pending.delete(msg.id);
        if (msg.error) p.reject(new Error(`${p.method}: ${msg.error.message}`));
        else p.resolve(msg.result);
      } else {
        for (const l of this.listeners) l(msg);
      }
    });
  }

  open() {
    return new Promise((resolve, reject) => {
      this.ws.addEventListener("open", () => resolve(), { once: true });
      this.ws.addEventListener("error", () => reject(new Error("DevTools WebSocket failed")), { once: true });
    });
  }

  send(method, params = {}, sessionId) {
    const id = this.nextId++;
    const payload = { id, method, params };
    if (sessionId) payload.sessionId = sessionId;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject, method });
      this.ws.send(JSON.stringify(payload));
    });
  }

  on(handler) { this.listeners.push(handler); }
  close() { try { this.ws.close(); } catch { /* ignore */ } }
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Injected before any page script: observers for CLS, paint, Event Timing, first grid row, late <link>.
const INSTRUMENTATION = `(() => {
  if (window.__perf) return;
  const P = window.__perf = { cls: 0, fcp: null, firstRow: null, lateCss: 0, events: [], rowsChangedAt: null };
  try { performance.setResourceTimingBufferSize(2000); } catch (e) {}
  const obs = (type, cb, extra) => { try { new PerformanceObserver((l) => l.getEntries().forEach(cb)).observe(Object.assign({ type, buffered: true }, extra)); } catch (e) {} };
  obs("layout-shift", (e) => { if (!e.hadRecentInput) P.cls += e.value; });
  obs("paint", (e) => { if (e.name === "first-contentful-paint") P.fcp = e.startTime; });
  obs("event", (e) => P.events.push({ name: e.name, start: e.startTime, duration: e.duration, interactionId: e.interactionId || 0 }), { durationThreshold: 16 });
  const check = () => {
    if (P.firstRow === null) {
      const row = document.querySelector("#grid-rows .grid-row");
      if (row && row.textContent.trim()) P.firstRow = performance.now();
    }
  };
  new MutationObserver((records) => {
    check();
    for (const r of records) {
      if (r.target && r.target.closest && r.target.closest("#grid-rows")) P.rowsChangedAt = performance.now();
      for (const n of r.addedNodes) {
        if (n.nodeName === "LINK" && n.rel === "stylesheet" && P.fcp !== null && !n.dataset.parser) P.lateCss++;
      }
    }
  }).observe(document, { childList: true, subtree: true, characterData: true });
})();`;

async function evaluate(cdp, session, expression, awaitPromise = false) {
  const res = await cdp.send("Runtime.evaluate", { expression, returnByValue: true, awaitPromise }, session);
  if (res.exceptionDetails) throw new Error(`page error: ${res.exceptionDetails.text} ${res.exceptionDetails.exception?.description || ""}`);
  return res.result.value;
}

async function waitFor(cdp, session, expression, timeoutMs, what) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (await evaluate(cdp, session, expression)) return;
    await sleep(50);
  }
  throw new Error(`timeout waiting for ${what}`);
}

async function collectLoad(cdp, session) {
  await waitFor(cdp, session, "window.__perf && window.__perf.firstRow !== null", 60_000, "first grid row");
  await sleep(SETTLE_MS);
  return evaluate(cdp, session, `(() => {
    const P = window.__perf;
    const res = performance.getEntriesByType("resource");
    const own = res.filter((r) => r.name.startsWith(location.origin));
    const stat = own.filter((r) => !r.name.includes("/api/"));
    const api = own.filter((r) => r.name.includes("/api/"));
    const byExt = (ext) => stat.filter((r) => new URL(r.name).pathname.endsWith(ext));
    const nav = performance.getEntriesByType("navigation")[0];
    return {
      firstRowMs: P.firstRow, cls: P.cls, fcp: P.fcp, cssLateInjections: P.lateCss,
      requests: own.length + 1, staticRequests: stat.length, apiRequests: api.length,
      bytes: own.reduce((a, r) => a + (r.transferSize || 0), 0) + (nav.transferSize || 0),
      jsBytes: byExt(".js").reduce((a, r) => a + (r.decodedBodySize || 0), 0),
      jsFiles: byExt(".js").length, cssFiles: byExt(".css").length,
      notModified: own.filter((r) => r.responseStatus === 304).length,
      apiMaxMs: api.reduce((m, r) => Math.max(m, r.responseEnd - r.requestStart), 0),
    };
  })()`);
}

async function mouse(cdp, session, type, x, y, extra = {}) {
  await cdp.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra }, session);
}

async function click(cdp, session, x, y) {
  await mouse(cdp, session, "mouseMoved", x, y, { button: "none", clickCount: 0 });
  await mouse(cdp, session, "mousePressed", x, y);
  await mouse(cdp, session, "mouseReleased", x, y);
}

async function centerOf(cdp, session, selector) {
  const box = await evaluate(cdp, session, `(() => {
    const el = document.querySelector(${JSON.stringify(selector)});
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  })()`);
  if (!box) throw new Error(`element not found: ${selector}`);
  return box;
}

async function pressKey(cdp, session, key, code, vk, text) {
  const base = { key, code, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk };
  await cdp.send("Input.dispatchKeyEvent", { type: text ? "keyDown" : "rawKeyDown", text, ...base }, session);
  await cdp.send("Input.dispatchKeyEvent", { type: "keyUp", ...base }, session);
}

/** Runs an interaction and returns { inp, toRows } using Event Timing and the grid mutation clock. */
async function measureInteraction(cdp, session, action) {
  const mark = () => evaluate(cdp, session, "window.__perf.rowsChangedAt = null; window.__perf.t0 = performance.now(); 0");
  await evaluate(cdp, session, "window.__perf.events = []; 0");
  await mark();
  await action(mark);
  await sleep(SETTLE_MS / 3);
  const res = await evaluate(cdp, session, `({ events: window.__perf.events, rowsChangedAt: window.__perf.rowsChangedAt, t0: window.__perf.t0 })`);
  return {
    inp: interactionDuration(res.events),
    toRows: res.rowsChangedAt === null ? 0 : Math.max(0, res.rowsChangedAt - res.t0),
  };
}

async function measureInteractions(cdp, session, searchTerm) {
  const out = { inp: {}, toRows: {} };
  const row = await centerOf(cdp, session, "#grid-rows .grid-row:nth-child(3)");
  out.inp.click = (await measureInteraction(cdp, session, () => click(cdp, session, row.x, row.y))).inp;
  out.inp.keys = (await measureInteraction(cdp, session, async () => {
    for (let i = 0; i < 5; i++) { await pressKey(cdp, session, "ArrowDown", "ArrowDown", 40); await sleep(40); }
    for (let i = 0; i < 2; i++) { await pressKey(cdp, session, "ArrowUp", "ArrowUp", 38); await sleep(40); }
  })).inp;
  // Filter: pick a severity option that differs from the current one, then click Apply.
  await evaluate(cdp, session, `(() => {
    const s = document.getElementById("sev-select");
    const next = [...s.options].find((o) => o.value !== s.value && o.value !== "");
    if (next) { s.value = next.value; s.dispatchEvent(new Event("change", { bubbles: true })); }
    0;
  })()`);
  const apply = await centerOf(cdp, session, "#filter-form button[type=submit]");
  const filter = await measureInteraction(cdp, session, () => click(cdp, session, apply.x, apply.y));
  out.inp.filter = filter.inp;
  out.toRows.filter = filter.toRows;
  await evaluate(cdp, session, `document.getElementById("filter-reset").click(); 0`);
  await sleep(500);
  const box = await centerOf(cdp, session, "#search-input");
  const search = await measureInteraction(cdp, session, async (mark) => {
    await click(cdp, session, box.x, box.y);
    for (const ch of searchTerm) { await pressKey(cdp, session, ch, `Key${ch.toUpperCase()}`, ch.toUpperCase().charCodeAt(0), ch); await sleep(20); }
    await mark(); // time to rows counts from Enter, not from typing
    await pressKey(cdp, session, "Enter", "Enter", 13, "\r");
  });
  out.inp.search = search.inp;
  out.toRows.search = search.toRows;
  await evaluate(cdp, session, `document.getElementById("search-clear").click(); 0`);
  await sleep(500);
  return out;
}

async function measureScroll(cdp, session) {
  const target = await centerOf(cdp, session, "#grid-viewport");
  const events = [];
  const onMsg = (msg) => { if (msg.method === "Tracing.dataCollected") events.push(...msg.params.value); };
  cdp.on(onMsg);
  const done = new Promise((resolve) => cdp.on((msg) => { if (msg.method === "Tracing.tracingComplete") resolve(); }));
  await cdp.send("Tracing.start", {
    traceConfig: { includedCategories: ["devtools.timeline"], recordMode: "recordAsMuchAsPossible" },
    transferMode: "ReportEvents",
  });
  await sleep(200);
  for (let i = 0; i < WHEEL_EVENTS; i++) {
    await cdp.send("Input.dispatchMouseEvent", { type: "mouseWheel", x: target.x, y: target.y, deltaX: 0, deltaY: 100 }, session);
    await sleep(16);
  }
  await sleep(300);
  await cdp.send("Tracing.end");
  await done;
  return analyzeTrace(events, WHEEL_EVENTS);
}

async function launchBrowser(opts, profileDir) {
  const exe = findBrowser(opts.browser);
  const args = [
    `--user-data-dir=${profileDir}`, "--remote-debugging-port=0", "--no-first-run", "--no-default-browser-check",
    "--disable-extensions", "--disable-background-networking", "--disable-sync", "--disable-default-apps",
    "--window-size=1600,900", "--force-device-scale-factor=1",
  ];
  if (!opts.headed) args.push("--headless=new");
  if (typeof process.getuid === "function" && process.getuid() === 0) args.push("--no-sandbox");
  args.push("about:blank");
  const child = spawnTracked(exe, args, { stdio: ["ignore", "ignore", "pipe"] });
  const match = await waitForLine(child, child.stderr, /DevTools listening on (ws:\/\/\S+)/, 30_000, "browser DevTools endpoint");
  return { child, wsUrl: match[1] };
}

async function generateCase(opts, tmp) {
  const out = path.join(tmp, "bench");
  const args = [path.join(ROOT, "tools", "bench.py"), "--out", out, "--keep", "--max-rss-mb", "0"];
  if (opts.large || opts.sizeMb) {
    args.push("--size-mb", String(opts.sizeMb ?? 500), "--adapters", String(opts.adapters ?? 8), "--profile", opts.profile ?? "info");
  } else {
    args.push("--quick");
  }
  const env = { ...process.env, PYTHONPATH: path.join(ROOT, "src") + (process.env.PYTHONPATH ? path.delimiter + process.env.PYTHONPATH : "") };
  await runToCompletion(opts.python, args, { env, cwd: ROOT });
  return { dataDir: path.join(out, "data") };
}

async function startServer(opts, dataDir) {
  const env = { ...process.env, PYTHONPATH: path.join(ROOT, "src") + (process.env.PYTHONPATH ? path.delimiter + process.env.PYTHONPATH : ""), PYTHONUNBUFFERED: "1" };
  const child = spawnTracked(opts.python, ["-m", "dmslog", "--data-dir", dataDir, "serve", "--no-browser", "--port", "0"], {
    env, cwd: ROOT, stdio: ["ignore", "pipe", "pipe"],
  });
  const match = await waitForLine(child, child.stdout, /(http:\/\/127\.0\.0\.1:\d+\/)\?token=(\S+)/, 60_000, "dmslog serve URL");
  return { base: match[1], url: `${match[1]}?token=${match[2]}` };
}

// ---------------------------------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------------------------------

export async function measure(opts) {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "dmslog-uiperf-"));
  tempDirs.add(tmp);
  const profile = path.join(tmp, "profile");
  fs.mkdirSync(profile);
  let cdp = null;
  try {
    console.error("ui_perf: generating the synthetic case with tools/bench.py");
    const { dataDir } = await generateCase(opts, tmp);
    console.error("ui_perf: starting dmslog serve");
    const server = await startServer(opts, dataDir);
    console.error("ui_perf: starting the browser");
    const browser = await launchBrowser(opts, profile);
    cdp = new Cdp(browser.wsUrl);
    await cdp.open();
    const { targetId } = await cdp.send("Target.createTarget", { url: "about:blank" });
    const { sessionId: session } = await cdp.send("Target.attachToTarget", { targetId, flatten: true });
    for (const domain of ["Page", "Runtime", "Network"]) await cdp.send(`${domain}.enable`, {}, session);
    await cdp.send("Emulation.setDeviceMetricsOverride", { width: 1600, height: 900, deviceScaleFactor: 1, mobile: false }, session);
    await cdp.send("Page.addScriptToEvaluateOnNewDocument", { source: INSTRUMENTATION }, session);
    const settleLoad = async () => collectLoad(cdp, session);

    // Warm-up: exchanges the start token for the session cookie; not measured.
    await cdp.send("Page.navigate", { url: server.url }, session);
    await settleLoad();
    if (opts.cpu > 1) await cdp.send("Emulation.setCPUThrottlingRate", { rate: opts.cpu }, session);

    console.error("ui_perf: measuring open");
    await cdp.send("Network.clearBrowserCache", {}, session);
    await cdp.send("Page.navigate", { url: server.base }, session);
    const open = await settleLoad();
    console.error("ui_perf: measuring reload");
    await cdp.send("Page.reload", {}, session);
    const reload = await settleLoad();
    console.error("ui_perf: measuring interactions");
    const inter = await measureInteractions(cdp, session, opts.searchTerm);
    console.error(`ui_perf: measuring scroll (${WHEEL_EVENTS} wheel events)`);
    await cdp.send("Page.navigate", { url: server.base }, session);
    await settleLoad();
    const scroll = await measureScroll(cdp, session);
    const raw = { open, reload, inp: inter.inp, toRows: inter.toRows, scroll };
    return { raw, measures: buildMeasures(raw), browser: await cdp.send("Browser.getVersion").then((v) => v.product).catch(() => "unknown") };
  } finally {
    if (cdp) cdp.close();
    cleanup();
  }
}

export async function main(argv) {
  let opts;
  try {
    opts = parseArgs(argv);
  } catch (err) {
    console.error(`ui_perf: ${err.message}\n\n${USAGE}`);
    return 2;
  }
  if (opts.help) { console.log(USAGE); return 0; }
  if (Number(process.versions.node.split(".")[0]) < 22 || typeof WebSocket === "undefined") {
    console.error("ui_perf: Node >= 22 (native WebSocket) is required");
    return 2;
  }
  const budgets = JSON.parse(fs.readFileSync(opts.budgets, "utf-8"));
  const problems = validateBudgets(budgets);
  if (problems.length) { console.error(`ui_perf: invalid budget file:\n  ${problems.join("\n  ")}`); return 2; }
  const result = await measure(opts);
  const rows = compareBudgets(result.measures, budgets);
  const report = {
    schema: 1, browser: result.browser, cpu: opts.cpu, case: opts.large || opts.sizeMb ? "custom" : "quick",
    measures: result.measures, raw: result.raw, comparison: rows, status: hasFailures(rows) ? "FAIL" : "PASS",
  };
  console.log(formatTable(rows));
  console.log(`\nBrowser: ${report.browser}; CPU ${opts.cpu}x; case: ${report.case}. Baseline column: analysis 3 (3.5M records, CPU 4x).`);
  console.log(`Overall: ${report.status}`);
  console.log("\nJSON:");
  console.log(JSON.stringify(report, null, 2));
  if (opts.json) fs.writeFileSync(opts.json, JSON.stringify(report, null, 2) + "\n", { encoding: "utf-8" });
  return opts.reportOnly ? 0 : report.status === "PASS" ? 0 : 1;
}

const isMain = process.argv[1] && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url;
if (isMain) {
  for (const sig of ["SIGINT", "SIGTERM", "SIGHUP"]) process.on(sig, () => { cleanup(); process.exit(130); });
  process.on("exit", cleanup);
  main(process.argv.slice(2)).then(
    (code) => { cleanup(); process.exitCode = code; },
    (err) => { console.error(`ui_perf: ${err.stack || err.message}`); cleanup(); process.exitCode = 2; },
  );
}
